@extends('layouts.app')
@section('title', ucfirst($tipo).' | Manutenção Tatuí')
@section('heading', ucfirst($tipo))
@section('content')<div class="mb-4"><div class="eyebrow">Administração</div><h2 class="h3">{{ ucfirst($tipo) }}</h2><p class="text-secondary">Gerencie os registros utilizados nos chamados.</p></div><div class="panel p-4"><div class="d-flex justify-content-between mb-3"><input id="busca" class="form-control w-50" placeholder="Pesquisar..."><button id="novo" class="btn btn-primary">＋ Novo registro</button></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nome</th><th>Descrição</th><th>Ações</th></tr></thead><tbody id="rows"><tr><td colspan="3" class="text-center text-secondary">Carregando...</td></tr></tbody></table></div></div>@endsection
@section('scripts')<script>$(function(){let token=@json(session('api_token')),tipo=@json($tipo);function load(){ $.ajax({url:'/api/cadastros/'+tipo,headers:{Authorization:'Bearer '+token}}).done(d=>$('#rows').html(d.data.map(x=>`<tr><td>${x.nome}</td><td>${x.descricao||'Sem descrição.'}</td><td><button class="btn btn-sm btn-outline-danger del" data-id="${x.id}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="3" class="text-center text-secondary">Sem registros.</td></tr>'))}load();$('#busca').on('input',load);$('#novo').on('click',function(){Swal.fire({title:'Novo registro',input:'text',inputLabel:'Nome',showCancelButton:true,confirmButtonText:'Salvar'}).then(r=>{if(r.isConfirmed&&r.value)$.ajax({url:'/api/cadastros/'+tipo,method:'POST',headers:{Authorization:'Bearer '+token},data:{nome:r.value}}).done(load)})});$('#rows').on('click','.del',function(){let id=$(this).data('id');Swal.fire({title:'Excluir registro?',icon:'warning',showCancelButton:true,confirmButtonText:'Excluir'}).then(r=>{if(r.isConfirmed)$.ajax({url:'/api/cadastros/'+tipo+'/'+id,method:'DELETE',headers:{Authorization:'Bearer '+token}}).done(load)})})});</script>@endsection